import{_ as t,o as a,c as i,a3 as d,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/tutorials-gs-ep-jahre.png",k=JSON.parse('{"title":"Die Jahre der Schuleingangsphase eintragen","description":"","frontmatter":{"title":"Die Jahre der Schuleingangsphase eintragen","source_pageid":1501,"source_revision":7204},"headers":[],"relativePath":"schild3/schueler/eintragung-der-ep-jahre-tutorial.md","filePath":"schild3/schueler/eintragung-der-ep-jahre-tutorial.md"}'),h={name:"schild3/schueler/eintragung-der-ep-jahre-tutorial.md"};function l(g,r,o,u,c,p){return a(),i("div",null,[...r[0]||(r[0]=[d('<h1 id="die-jahre-der-schuleingangsphase-eintragen" tabindex="-1">Die Jahre der Schuleingangsphase eintragen <a class="header-anchor" href="#die-jahre-der-schuleingangsphase-eintragen" aria-label="Permalink to &quot;Die Jahre der Schuleingangsphase eintragen&quot;">​</a></h1><p>Erfassen Sie das EP-Jahr im jeweiligen Lernabschnitt. Der Statistikjahrgang und die zusätzliche Angabe E1, E2 oder E3 werden dabei getrennt geführt.</p><p><a href="/bilder/schueler/tutorials-gs-ep-jahre.png"><img src="'+s+'" alt="Erfassung der EP-Jahre im jeweiligen Lernabschnitt" loading="lazy"></a></p><p><em>Erfassung der EP-Jahre im jeweiligen Lernabschnitt</em></p><p>In der Grundschule werden die <strong>Jahrgänge 01, 02, 03 und 04</strong> verwendet. Für Schülerinnen und Schüler der Jahrgänge <strong>01 und 02</strong> wird zusätzlich das <strong>EP-Jahr E1, E2 oder E3</strong> erfasst. Es gibt an, im wievielten Schuljahr sich das Kind innerhalb der Jahrgänge 01 und 02 befindet; es ist kein eigener Jahrgang.</p><table tabindex="0"><thead><tr><th>EP-Jahr</th><th>Bedeutung</th></tr></thead><tbody><tr><td>E1</td><td>Erstes Schuljahr innerhalb der Jahrgänge 01 und 02</td></tr><tr><td>E2</td><td>Zweites Schuljahr innerhalb der Jahrgänge 01 und 02</td></tr><tr><td>E3</td><td>Drittes Schuljahr innerhalb der Jahrgänge 01 und 02</td></tr></tbody></table><h2 id="ep-jahr-in-jedem-halbjahr-zuordnen" tabindex="-1">EP-Jahr in jedem Halbjahr zuordnen <a class="header-anchor" href="#ep-jahr-in-jedem-halbjahr-zuordnen" aria-label="Permalink to &quot;EP-Jahr in jedem Halbjahr zuordnen&quot;">​</a></h2><ol><li>Öffnen Sie <strong>Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben</strong>.</li><li>Wählen Sie den zu bearbeitenden Lernabschnitt.</li><li>Tragen Sie bei Schülerinnen und Schülern der Jahrgänge <strong>01 und 02</strong> das passende <strong>EP-Jahr E1, E2 oder E3</strong> ein. Prüfen und erfassen Sie diese Zuordnung <strong>in jedem Halbjahr</strong>.</li></ol><h2 id="anzeige-und-korrektur-in-individualdaten-i" tabindex="-1">Anzeige und Korrektur in Individualdaten I <a class="header-anchor" href="#anzeige-und-korrektur-in-individualdaten-i" aria-label="Permalink to &quot;Anzeige und Korrektur in Individualdaten I&quot;">​</a></h2><p>Das momentane EP-Jahr wird zusätzlich in der <strong>Schülertabelle</strong> gespeichert und unter <strong>Individualdaten I ➜ Aktuelle Laufbahn</strong> angezeigt. In den Jahrgängen <strong>01 und 02</strong> ist es dort <strong>nicht editierbar</strong>; die Zuordnung erfolgt im jeweiligen Halbjahr.</p><p>Ab <strong>Jahrgang 03</strong> entfällt die Eingabemöglichkeit unter <strong>Akt. Halbjahr ➜ Allgemeine Angaben</strong>. Der gespeicherte Wert bleibt unter <strong>Individualdaten I</strong> sichtbar und kann dort bei Bedarf <strong>zur Korrektur bearbeitet</strong> werden.</p><h2 id="weitere-verarbeitung" tabindex="-1">Weitere Verarbeitung <a class="header-anchor" href="#weitere-verarbeitung" aria-label="Permalink to &quot;Weitere Verarbeitung&quot;">​</a></h2><p>Beim Export nach ASDPC im Zuge der Statistik wird der Jahrgang automatisch korrekt auf die von ASDPC erwarteten Werte gesetzt.</p><p>Unter <strong>Verwaltung ➜ Werkzeuge</strong> steht Ihnen die Funktion <strong>EP-Jahr abgleichen</strong> zur Verfügung.</p><p>Hierbei wird aus allen Lernabschnitten das höchste EP-Jahr in den Individualdaten I eingetragen.</p>',15),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Achten Sie nach Möglichkeit darauf, dass einer weiterführenden Schule das korrekte EP-Jahr - zum Beispiel durch die Erziehungsberechtigten - gemeldet werden kann, damit dort das Ende der Schulpflicht korrekt berechnet werden kann.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Eintragung_der_EP-Jahre_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 7204.")],-1)])])}const m=t(h,[["render",l]]);export{k as __pageData,m as default};
